        &result,
        Err(ExecutorError::Artifact(JournalError::SequenceOverflow))
    );
    if !got {
        return Err(format!("expected SequenceOverflow after u64::MAX, got: {result:?}").into());
    }

    let counter_after = read_counter(&journal)?;
    if counter_after != Some(u64::MAX) {
        return Err("counter should remain at u64::MAX after overflow".into());
    }
    fixture.check(&journal, &artifact, RuntimePolicy::Relaxed)?;
    Ok(())
}

