    let counter = read_counter(&journal)?;
    if counter.is_some() {
        return Err("counter should be None before retry".into());
    }
    if journal.compiled_ir.iter().next().is_some() {
        return Err("compiled_ir should be empty before retry".into());
    }

    let artifact = fixture.submit(&journal, RuntimePolicy::Strict)?;
    if artifact.accepted_at_seq.get() != 1 {
